PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Roles(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Users(Id INTEGER PRIMARY KEY, FullName TEXT NOT NULL, Login TEXT NOT NULL UNIQUE, PasswordHash TEXT NOT NULL, Email TEXT NOT NULL, RoleId INTEGER NOT NULL REFERENCES Roles(Id));
CREATE TABLE IF NOT EXISTS ProductTypes(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Products(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, TypeId INTEGER NOT NULL REFERENCES ProductTypes(Id), Description TEXT NOT NULL, Composition TEXT NOT NULL, PriceCents INTEGER NOT NULL CHECK(PriceCents >= 0), Discount INTEGER NOT NULL CHECK(Discount BETWEEN 0 AND 100), DiscountActive INTEGER NOT NULL CHECK(DiscountActive IN (0,1)), MinStock INTEGER NOT NULL CHECK(MinStock >= 0), Stock INTEGER NOT NULL CHECK(Stock >= 0), ImagePath TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS OrderStatuses(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Orders(Id INTEGER PRIMARY KEY, UserId INTEGER NOT NULL REFERENCES Users(Id), Address TEXT NOT NULL CHECK(length(trim(Address)) > 0), StatusId INTEGER NOT NULL REFERENCES OrderStatuses(Id), CreatedAt TEXT NOT NULL, DeliveryAt TEXT);
CREATE TABLE IF NOT EXISTS OrderItems(OrderId INTEGER NOT NULL REFERENCES Orders(Id) ON DELETE CASCADE, ProductId INTEGER NOT NULL REFERENCES Products(Id) ON DELETE RESTRICT, Quantity INTEGER NOT NULL CHECK(Quantity > 0), UnitPriceCents INTEGER NOT NULL CHECK(UnitPriceCents >= 0), PRIMARY KEY(OrderId,ProductId));
CREATE INDEX IF NOT EXISTS IX_Products_TypeId ON Products(TypeId);
CREATE INDEX IF NOT EXISTS IX_Orders_UserId ON Orders(UserId);
